	scope: HevyRequestObservationScope | undefined,
	operation: () => Promise<T>,
): Promise<T> {
	if (!scope?.run) return operation();
	let started = false;
	const trackedOperation = () => {
		started = true;
		return operation();
	};
	try {
		return scope.run(trackedOperation);
	} catch (error) {
		if (started) throw error;
		return operation();
	}
}

